{"model": "claude-agentsight-mock", "max_tokens": 64, "messages": [{"role": "assistant", "content": "Our office LAN (192.168.10.0/24) must reach the internet through our static public IP 203.0.113.2/30, gateway 203.0.113.1. Configure the firewall for stable, centrally-managed egress.

Site notes: the firewall `fw` has LAN on eth1 (192.168.10.1/24) and the ISP hand-off on eth2 (not configured yet).
PLAN:
ip addr add 203.0.113.2/30 dev eth2 2>/dev/null; ip link set eth2 up; ip route replace default via 203.0.113.1

cat > /etc/nftables.conf <<'NFT'
flush ruleset
table inet filter {
  chain input { type filter hook input priority 0; policy accept; }
  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept
    iifname "eth1" oifname "eth2" accept
  }
}
table ip nat {
  chain postrouting {
    type nat hook postrouting priority 100;
    oifname "eth2" ip saddr 192.168.10.0/24 snat to 203.0.113.2
  }
}
NFT

fw-commit >/dev/null"}]}
